CREATE VIEW dbo.IV_Q$AVALIA_USADO_ENTRADA ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , MODELO_DO_EQUIPAMENT, ENDERECO_PARA_A_AVAL, EXPECTATIVA_DE_VALOR, CHASSI_DO_EQUIPAMENT, TIPO_DO_EQUIPAMENTO, MARCA, ANO_EQUIPAMENTO, VALOR_DA_AVALIACAO, HORIMETRO, N__SERIE, COR, MOTOR___FUNCIONAMENT, VAZAMENTOS___AGUA, VAZAMENTO___OLEO, VAZAMENTO___COMBUSTI, PARTE_ELETRICA___BAT, PARTE_ELETRICA___PAR, PNEUS_DIANTEIRO_DIRE, PNEUS_DIANTEIRO_ESQU, PNEUS_TRASEIRO_DIREI, PNEUS_TRASEIRO_ESQUE, VALOR_FINAL_DE_AVALI, COM_RETIRADA_DO_USAD, RETIRADA_DO_USADO1, COMO_SERA_REALIZADO_, COM_CABINE, PESO_DIANTEIRO, PESO_TRASEIRO, EMBREAGEM, TERCEIRO_PONTO, TRANSMISSAO, SISTEMA_INDUSTRIAL, ELEVADOR)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.MODELO_DO_EQUIPAMENT, TABF.ENDERECO_PARA_A_AVAL, TABF.EXPECTATIVA_DE_VALOR, TABF.CHASSI_DO_EQUIPAMENT, TABF.TIPO_DO_EQUIPAMENTO, TABF.MARCA, TABF.ANO_EQUIPAMENTO, TABF.VALOR_DA_AVALIACAO, TABF.HORIMETRO, TABF.N__SERIE, TABF.COR, TABF.MOTOR___FUNCIONAMENT, TABF.VAZAMENTOS___AGUA, TABF.VAZAMENTO___OLEO, TABF.VAZAMENTO___COMBUSTI, TABF.PARTE_ELETRICA___BAT, TABF.PARTE_ELETRICA___PAR, TABF.PNEUS_DIANTEIRO_DIRE, TABF.PNEUS_DIANTEIRO_ESQU, TABF.PNEUS_TRASEIRO_DIREI, TABF.PNEUS_TRASEIRO_ESQUE, TABF.VALOR_FINAL_DE_AVALI, TABF.COM_RETIRADA_DO_USAD, TABF.RETIRADA_DO_USADO1, TABF.COMO_SERA_REALIZADO_, TABF.COM_CABINE, TABF.PESO_DIANTEIRO, TABF.PESO_TRASEIRO, TABF.EMBREAGEM, TABF.TERCEIRO_PONTO, TABF.TRANSMISSAO, TABF.SISTEMA_INDUSTRIAL, TABF.ELEVADOR    FROM IV_Q_AVALIA_USADO_ENTRADA TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 